    fn capacity(&self) -> u32 {
        self.depth * 2
    }
}

impl fmt::Display for Burrow {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "Burrow({})", self.depth)
    }
}

fn main() {
    println!("{}", Hollow.describe());
    let b = Burrow { depth: 30 };
    println!("{}", b.describe());
